std::priority_queue<TreeNode*, std::vector<TreeNode*>, CompareNodes> pq;

for (int i = 0; i < size; ++i) {
    pq.push(new TreeNode(values[i], freqs[i]));
}

while (pq.size() > 1) {
    TreeNode* left = pq.top();
    pq.pop();
    TreeNode* right = pq.top();
    pq.pop();

    TreeNode* parent = new TreeNode('\0', left->freq + right->freq);
    parent->left = left;
    parent->right = right;
    pq.push(parent);
}

return pq.empty() ? nullptr : pq.top();

// END_CODE

